        mov     byte [menuKey__ret], 0
        ret

; ============================================== u16 menuBlob ====

menuBlob:
; ---- if ( m == 0 ) return addr( tEdit )
        mov     ax, [menuBlob__m]
        test    ax, ax
        jne     .L94                        ; unsigned ==
        mov     ax, tEdit                   ; link-time constant
        mov     [menuBlob__ret], ax
        ret
.L94:
; ---- if ( m == 1 ) return addr( tView )
        mov     ax, [menuBlob__m]
        cmp     ax, 1
        jne     .L97                        ; unsigned ==
        mov     ax, tView                   ; link-time constant
        mov     [menuBlob__ret], ax
        ret
.L97:
; ---- if ( m == 2 ) return addr( tFile )
        mov     ax, [menuBlob__m]
        cmp     ax, 2
        jne     .L100                       ; unsigned ==
        mov     ax, tFile                   ; link-time constant
        mov     [menuBlob__ret], ax
        ret
.L100:
; ---- return addr( tNothing )
        mov     ax, tNothing                ; link-time constant
        mov     [menuBlob__ret], ax
        ret

; ============================================== u16 menuCount ====

menuCount:
; ---- u16 menuCount() => strParts( addr( tTitles ) )
        mov     ax, tTitles                 ; link-time constant
        mov     [strParts__at], ax
        call    strParts
        mov     ax, [strParts__ret]
        mov     [menuCount__ret], ax
        ret

; ============================================== u16 menuTitle ====

menuTitle:
; ---- a16 menuTitle( u16 m ) => nthStr( addr( tTitles ), m )
        mov     ax, tTitles                 ; link-time constant
        mov     [nthStr__at], ax
        mov     ax, [menuTitle__m]
        mov     [nthStr__n], ax
        call    nthStr
        mov     ax, [nthStr__ret]
        mov     [menuTitle__ret], ax
        ret

; ============================================== u16 menuItemCount ====

menuItemCount:
; ---- u16 menuItemCount( u16 m ) => strParts( menuBlob( m ) )
        mov     ax, [menuItemCount__m]
        mov     [menuBlob__m], ax
        call    menuBlob
        mov     ax, [menuBlob__ret]
        mov     [strParts__at], ax
        call    strParts
        mov     ax, [strParts__ret]
        mov     [menuItemCount__ret], ax
        ret

; ============================================== u16 menuItemText ====

menuItemText:
; ---- a16 menuItemText( u16 m, u16 i ) => nthStr( menuBlob( m ), i )
        mov     ax, [menuItemText__m]
        mov     [menuBlob__m], ax
        call    menuBlob
        mov     ax, [menuBlob__ret]
        push    ax                          ; argument evaluated before any is stored
        mov     ax, [menuItemText__i]
        mov     [nthStr__n], ax
        pop     ax
        mov     [nthStr__at], ax
        call    nthStr
        mov     ax, [nthStr__ret]
        mov     [menuItemText__ret], ax
        ret

; ============================================== sub press ====

press:
; ---- res = menuKey( k )
        mov     ax, [press__k]
        mov     [menuKey__k], ax
        call    menuKey
        mov     al, [menuKey__ret]
        xor     ah, ah                      ; u8 -> u16
        mov     [res], al                   ; narrowed to u8
        ret

; ============================================== sub show ====

show:
; ---- putNumber( u16( menuUp() ) )
        call    menuUp
        mov     al, [menuUp__ret]
        xor     ah, ah                      ; bool -> u16
        mov     [putNumber__n], ax
        call    putNumber
; ---- putChar( ' ' )
        mov     byte [putChar__c], 32
        call    putChar
; ---- putNumber( menuAt() )
        call    menuAt
        mov     ax, [menuAt__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- putChar( ' ' )
        mov     byte [putChar__c], 32
        call    putChar
; ---- putNumber( menuItemAt() )
        call    menuItemAt
        mov     ax, [menuItemAt__ret]
        mov     [putNumber__n], ax
        call    putNumber
; ---- newline()
        call    newline
        ret

; ==================================================== int helpers ====
; One per distinct interrupt: the literal is baked in, so the register
; sync is emitted once rather than at every call site.

int21:
        mov     ax, [_ax]
        mov     bx, [_bx]
        mov     cx, [_cx]
        mov     dx, [_dx]
        mov     si, [_si]
        mov     di, [_di]
        int     0x21
        mov     [_ax], ax
        mov     [_bx], bx
        mov     [_cx], cx
        mov     [_dx], dx
        mov     [_si], si
        mov     [_di], di
        ret

; ============================================================ data ====

; ---- reserved globals: the machine registers ----
_ax:            dw      0
_al:            equ     _ax
_ah:            equ     _ax + 1
_bx:            dw      0
_bl:            equ     _bx
_bh:            equ     _bx + 1
_cx:            dw      0
_cl:            equ     _cx
_ch:            equ     _cx + 1
_dx:            dw      0
_dl:            equ     _dx
_dh:            equ     _dx + 1
_si:            dw      0
_di:            dw      0

; ---- variables ----
putChar__c:     db      0        ; u8
putNumber__n:   dw      0        ; u16
strParts__at:   dw      0        ; u16
strParts__ret:  dw      0        ; u16
nthStr__at:     dw      0        ; u16
nthStr__n:      dw      0        ; u16
nthStr__ret:    dw      0        ; u16
momenu__showing: db      0        ; bool
momenu__curMenu: dw      0        ; u16
momenu__curItem: dw      0        ; u16
menuUp__ret:    db      0        ; bool
menuAt__ret:    dw      0        ; u16
menuItemAt__ret: dw      0        ; u16
momenu__fold__c: db      0        ; u8
momenu__fold__ret: db      0        ; u8
momenu__itemsHere__ret: dw      0        ; u16
menuShow__m:    dw      0        ; u16
menuOpenFor__c: db      0        ; u8
menuOpenFor__ret: db      0        ; bool
momenu__menuGo__by: dw      0        ; u16
menuJump__c:    db      0        ; u8
menuJump__ret:  db      0        ; bool
menuKey__k:     dw      0        ; u16
menuKey__ret:   db      0        ; u8
menuBlob__m:    dw      0        ; u16
menuBlob__ret:  dw      0        ; u16
menuCount__ret: dw      0        ; u16
menuTitle__m:   dw      0        ; u16
menuTitle__ret: dw      0        ; u16
menuItemCount__m: dw      0        ; u16
menuItemCount__ret: dw      0        ; u16
menuItemText__m: dw      0        ; u16
menuItemText__i: dw      0        ; u16
menuItemText__ret: dw      0        ; u16
res:            db      0        ; u8
press__k:       dw      0        ; u16
putNumber__i:   db      0        ; u8
strParts__n:    dw      0        ; u16
strParts__i:    dw      0        ; u16
nthStr__i:      dw      0        ; u16
nthStr__seen:   dw      0        ; u16
menuOpenFor__m: dw      0        ; u16
momenu__menuGo__i: dw      0        ; u16
momenu__menuGo__m: dw      0        ; u16
menuJump__i:    dw      0        ; u16
menuJump__n:    dw      0        ; u16
menuJump__item: dw      0        ; u16

; ---- arrays ----
tTitles:        db      'Edit$View$File$Nothing$', 0        ; u8[24] const
tEdit:          db      'Cut$Copy$Paste$Character$', 0        ; u8[26] const
tView:          db      'Explorer$', 0        ; u8[10] const
tFile:          db      'New$Open$Save$', 0        ; u8[15] const
tNothing:       times 1 db 0        ; u8[1]
putNumber__digits: times 5 db 0        ; u8[5]

; ============================================================ heap ====
; No storage is emitted - a .COM owns everything past its image, so
; these are addresses and NASM does the arithmetic.

_hstack:        equ     272        ; 16 worst-case + 256 interrupt reserve
_htop:          equ     0FFFEh - _hstack

_hsize:         dw      _htop - _heap        ; NASM computes this
        align   2                           ; keep the u16 view aligned
_heap:
_heapw:         equ     _heap        ; same bytes, u16 view
